seq = "".join(l.strip() for l in open('region.fasta') if not l.startswith('>'))
N=len(seq)
comp = str.maketrans('ACGT','TGCA')
rc = seq.translate(comp)[::-1]

def ir_search(k):
    idx = {}
    for j in range(N-k+1):
        idx.setdefault(rc[j:j+k], []).append(j)
    hits=[]
    for i in range(N-k+1):
        a = seq[i:i+k]
        for j in idx.get(a, []):
            s2 = N-j-k   # start of arm2 on + strand
            if s2 > i:   # arm2 downstream of arm1
                hits.append((i,s2,k))
    return hits

for k in range(25,9,-1):
    h = ir_search(k)
    if h:
        print(f"arm length {k}: {len(h)} hits")
        for i,s2,k2 in sorted(h, key=lambda x:-(x[1]-x[0]))[:12]:
            print(f"   {seq[i:i+k2]}  at {i+1}-{i+k2}  ... {s2+1}-{s2+k2}   loop/target span {s2-i-k2} bp")
        print()

