def dr(k):
    idx={}
    for i in range(N-k+1):
        idx.setdefault(seq[i:i+k],[]).append(i)
    out=[]
    for kk,pos in idx.items():
        if len(pos)>1:
            for a in pos:
                for b in pos:
                    if b-a>=1:
                        out.append((b-a,a,b))
    return sorted(out)
